from __future__ import annotations

import logging
import time
from datetime import datetime
from typing import Optional, Union, Literal, TYPE_CHECKING
from urllib.parse import urlparse, unquote
from uuid import uuid1

import allure
import requests
from requests import Response, Session

from pyvkteamsclient.survey.exceptions import (
    RatelimitException,
    MissingParameterException,
    ServerException,
    AccessDeniedException,
    HttpNotFoundException,
    BadRequestException,
    UserMustJoinByLinkException,
    RequestException,
    OrgstructureException,
)

if TYPE_CHECKING:
    from pyvkteamsclient.client import DesktopClient

event_response = None


class BaseClient(object):
    """
    !
    Базовый класс
    """

    logger = logging.getLogger(__name__)

    def __init__(
        self,
        session: Session,
        miniapps_api_url: str,
        account: DesktopClient,
        env: str = "SANDBOX",
    ):
        def assign_encoding(response: Response, *args, **kwargs) -> Response:
            response.encoding = "utf-8"
            return response

        self.session = session
        if not self.session.hooks["response"]:
            self.session.hooks["response"].append(self.allure_attach)
            self.session.hooks["response"].append(assign_encoding)

        self.url = miniapps_api_url
        self.account = account
        self.env = env

    @staticmethod
    def getReqId() -> str:
        """
        Генерация уникального ID запроса
        :return: str
        """
        return str(uuid1())

    def allure_attach(
        self,
        response: requests.Response,
        return_str: bool = False,
        *args,
        **kwargs,
    ):
        """
        Функция для логирования запроса-ответа в Allure отчете

        """
        response.encoding = "UTF-8"

        date_str = str(datetime.now())
        headers_str = "\n".join([f"{k}: {v}" for k, v in response.request.headers.items()])

        text = f"{date_str}\n" f"{response.request.method} {response.request.url}\n" f"{headers_str}\n"

        if response.request.body:
            if isinstance(response.request.body, str):
                text += "\n" f"{unquote(response.request.body)}"

            elif isinstance(response.request.body, (bytes, bytearray)) and len(response.request.body) < 1000:
                try:
                    text += "\n" f"{unquote(response.request.body.decode())}"
                except UnicodeDecodeError:
                    text += "\n" f"Bytes {len(response.request.body)}"

            else:
                text += "\n" f"{type(response.request.body)}"

        text = text.strip()

        headers_str = "\n".join([f"{k}: {v}" for k, v in response.headers.items()])

        text += f"\n\n{response.status_code} {response.reason}\n" f"{headers_str}\n"

        if response.text:
            if isinstance(response.text, str):
                text += "\n" f"{response.text}"
            else:
                text += "\n" f"{response.content.decode()}"

        self.logger.info(text)

        url_path = urlparse(response.url).path.replace("/", "_")

        allure.attach(
            text,
            name=f"{url_path}.log.txt",
            extension=allure.attachment_type.TEXT,
        )

        if return_str:
            return text
        return None

    def request(
        self,
        method: Literal["GET", "POST"],
        url: str,
        headers: Optional[dict] = None,
        params: Optional[dict] = None,
        json: Optional[dict] = None,
        data: Optional[dict] = None,
        files=None,
        ignore_check: bool = False,
        stream: bool = False,
        allow_redirects: bool = True,
    ) -> Union[dict, Response]:
        """
        Прокси-метод для всех запросов
        """
        request = self.session.prepare_request(
            requests.Request(
                method=method,
                url=url,
                headers=headers,
                params=params,
                json=json,
                data=data,
                files=files,
            ),
        )

        response = ValueError

        MAX_RETRIES = 2

        for i in range(MAX_RETRIES + 1):
            try:
                response = self.session.send(
                    request=request,
                    stream=stream,
                    allow_redirects=allow_redirects,
                )
                response.encoding = "UTF-8"

                if not ignore_check:
                    return self.check_response(response=response)

                else:
                    response_content_type = response.headers.get("Content-Type") or response.headers.get(
                        "content-type",
                        "generic",
                    )
                    self.logger.info(f"response_content_type: {response_content_type}")
                    if response_content_type.startswith("application/json"):
                        return response.json()
                    else:
                        return response

            except OrgstructureException:
                if i < MAX_RETRIES:
                    time.sleep(10 * i)
                    continue
                else:
                    raise

            except (
                AccessDeniedException,
                HttpNotFoundException,
                BadRequestException,
                ServerException,
            ):
                raise

            except RatelimitException:
                if i < MAX_RETRIES:
                    continue
                else:
                    raise

            except RequestException as error:
                if i == MAX_RETRIES or "Internal/folders" in url:
                    raise

                self.logger.error(error)

                request = self.session.prepare_request(
                    requests.Request(
                        method=method,
                        url=url,
                        headers=headers,
                        params=params,
                        json=json,
                        data=data,
                        files=files,
                    ),
                )

        else:
            if isinstance(response, Exception):
                raise response

            elif isinstance(response, Response):
                response.raise_for_status()
                return response
            else:
                return response

    def get_error_message(
        self,
        path_url: str,
        response_status_code: Union[str, int],
        response_status_text: str,
    ) -> str: ...

    def check_response(self, response: Response) -> Response:
        """Проверка кода ответа API"""
        try:
            response_json = response.json()
        except Exception as error:
            self.logger.error(error)
            response_json = {"not_json": True}

        try:
            response_status_code = int(
                response_json.get("status", {}).get("code")
                or response_json.get("response", {}).get("statusCode")
                or response_json.get("status")
                or response.status_code,
            )
        except AttributeError:
            response_status_code = response.status_code

        try:
            response_status_text = str(
                response_json.get("description")
                or response_json.get("response", {}).get("statusText")
                or response_json.get("status", {}).get("reason")
                or ":".join(
                    ["{id}-{error}".format(**x) for x in response_json.get("results", {}).get("failures", [])],
                )
                or "NoStatusText",
            )
        except AttributeError:
            response_status_text = "NoStatusText"

        if response_status_code == 330:
            raise RequestException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in [40008, 40403, 40405] and "Internal/orgstructure" in response.request.path_url:
            raise OrgstructureException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in [400, 40000]:
            raise BadRequestException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in [20070] and "Internal/group/members/add" in response.url:
            raise UserMustJoinByLinkException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif 200 <= response_status_code < 400 or 20000 <= response_status_code < 40000:
            if not response_json.get("not_json", False):
                return response_json
            return response

        elif response_status_code == 40401:
            return response

        elif response_status_code in [403, 40003, 40300]:
            if "auth check failed" in response_status_text:
                raise RequestException(
                    env=self.env,
                    path_url=response.request.path_url,
                    response_status_code=response_status_code,
                    response_status_text=response_status_text,
                    http_request_plain_text=self.allure_attach(response=response, return_str=True),
                )
            raise AccessDeniedException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in [404, 40400, 40004]:
            raise HttpNotFoundException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in [429, 430]:
            raise RatelimitException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif response_status_code in (460, 462, 40000):
            raise MissingParameterException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        elif 400 <= response_status_code < 500 or 40000 <= response_status_code < 50000:
            raise RequestException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

        else:
            raise ServerException(
                env=self.env,
                path_url=response.request.path_url,
                response_status_code=response_status_code,
                response_status_text=response_status_text,
                http_request_plain_text=self.allure_attach(response=response, return_str=True),
            )

    @allure.step("[GET] Запрос к API {path}")
    def get(self, path: str, allow_redirects: bool = True, **kwargs) -> dict:
        """
        Оболочка для GET запросов к api ICQ/Myteam

        :param path: path для запроса
        :param retry: Количество повторных попыток запроса
        :param full_url:
        :return: результат выполнения запроса (код и тело ответа)
        """
        return self.request(
            method="GET",
            url="/".join([self.url, path]),
            params=kwargs,
            headers={"Cookie": f"aimsid={self.account.aimsid}"},
            allow_redirects=allow_redirects,
        )

    @allure.step("[POST] Запрос к API {path}")
    def post(
        self,
        path: str,
        params: Optional[dict] = None,
        json: Optional[dict] = None,
        data: Optional[dict] = None,
        files=None,
        allow_redirects: bool = True,
    ) -> Union[dict, Response]:
        """
        Оболочка для POST запросов к api ICQ/Myteam

        :return: результат выполнения запроса (код и тело ответа)
        """
        return self.request(
            method="POST",
            url="/".join([self.url, path]),
            params=params,
            headers={"Cookie": f"aimsid={self.account.aimsid}"},
            json=json,
            data=data,
            files=files,
            allow_redirects=allow_redirects,
        )
